      .getOrCreate();

    // $example on$
    List<Row> data = Arrays.asList(
        RowFactory.create(0, Vectors.dense(1.0, 0.1, -1.0)),
        RowFactory.create(1, Vectors.dense(2.0, 1.1, 1.0)),
