    // $example on$
    QuantileDiscretizer discretizer = new QuantileDiscretizer()
      .setInputCol("hour")
      .setOutputCol("result")
      .setNumBuckets(3);

    Dataset<Row> result = discretizer.fit(df).transform(df);
    result.show(false);
    // $example off$
