    RFormula formula = new RFormula()
      .setFormula("clicked ~ country + hour")
      .setFeaturesCol("features")
      .setLabelCol("label");
    Dataset<Row> output = formula.fit(dataset).transform(dataset);
    output.select("features", "label").show();
    // $example off$
    spark.stop();
  }
